import React from 'react';

import { HistogramExploreKeyboardOverlay } from './HistogramExploreKeyboardOverlay.js';
import { HistogramExploreOverlay } from './HistogramExploreOverlay.js';
import { useZoomState } from '../../../hooks/store/selectors.js';
import { useHistogramInteractions } from '../../../hooks/useHistogramInteractions.js';

export const HistogramExploreMode = () => {
  const { activeKeyboardMode } = useZoomState();
  const { zoomX } = useHistogramInteractions();
  const isZoomXEnabled = zoomX?.enabled;

  return isZoomXEnabled && activeKeyboardMode ? (
    <HistogramExploreKeyboardOverlay />
  ) : (
    <HistogramExploreOverlay />
  );
};
